(5869157, 853003, 99263, '<td valign="top">Lovely abstract image with nice deep colors but it does not give me any sense of perspective as I don''t have a clue what it is and I have don''t have a reference point. 6</td>', 'Lovely abstract image with nice deep colors but it does not give me any sense of perspective as I don''t have a clue what it is and I have don''t have a reference point. 6', '2010-02-16 12:46:26.000000', NULL, 1),
(5869158, 852749, 99263, '<td valign="top">Not too strong on perspective as the steering wheel is too far on the outer edge of the frame thus diminishing the effect of depth. 5</td>', 'Not too strong on perspective as the steering wheel is too far on the outer edge of the frame thus diminishing the effect of depth. 5', '2010-02-16 12:46:31.000000', NULL, 1),
(5869159, 853225, 99263, '<td valign="top">Fun shot. Those are called perspectacles aren''t they? 5</td>', 'Fun shot. Those are called perspectacles aren''t they? 5', '2010-02-16 12:46:35.000000', NULL, 1),
(5869160, 852972, 99263, '<td valign="top">Not much feeling of perspective as there is a lack of depth. The barrels should have been right up in your face and not so close to the bottom of the frame. Also the focus should be on the barrels with the girl subjected to a greater depth of field. 5</td>', 'Not much feeling of perspective as there is a lack of depth. The barrels should have been right up in your face and not so close to the bottom of the frame. Also the focus should be on the barrels with the girl subjected to a greater depth of field. 5', '2010-02-16 12:46:40.000000', NULL, 1),
(5869161, 853233, 99263, '<td valign="top">I like the perspective of this but I myself am a friend of Jack''s. (without coke)<br/>5</td>', 'I like the perspective of this but I myself am a friend of Jack''s. (without coke)5', '2010-02-16 12:46:47.000000', NULL, 1),
(5869163, 853180, 99263, '<td valign="top">Interesting perspective. 5</td>', 'Interesting perspective. 5', '2010-02-16 12:46:52.000000', NULL, 1),
(5869164, 853214, 99263, '<td valign="top">Unusual perspective of this Merc. What happened? jacked? Carjacked? Someone stole the wheels? 5</td>', 'Unusual perspective of this Merc. What happened? jacked? Carjacked? Someone stole the wheels? 5', '2010-02-16 12:47:08.000000', NULL, 1),
(5869165, 852480, 99263, '<td valign="top">A pretty picture with reasonable perspective. 5</td>', 'A pretty picture with reasonable perspective. 5', '2010-02-16 12:47:13.000000', NULL, 1),
(5869166, 853092, 99263, '<td valign="top">You pegged this one for perspective. 5</td>', 'You pegged this one for perspective. 5', '2010-02-16 12:47:17.000000', NULL, 1),
(5869167, 852408, 99263, '<td valign="top">Interesting low down perspective. 5</td>', 'Interesting low down perspective. 5', '2010-02-16 12:47:21.000000', NULL, 1),
(5869168, 853248, 99263, '<td valign="top">Might have been more effective perspective wise if some more of the surroundings were visible so one could get a better feeling of depth and size. Like maybe zoomed out a bit more. 5</td>', 'Might have been more effective perspective wise if some more of the surroundings were visible so one could get a better feeling of depth and size. Like maybe zoomed out a bit more. 5', '2010-02-16 12:47:25.000000', NULL, 1),
(5869169, 852580, 99263, '<td valign="top">Good pov but it''s a pity that the complete front wheel is not in the frame. The power lines distract a bit too. I think a panned shot with the background motion blurred might have been more striking. 4</td>', 'Good pov but it''s a pity that the complete front wheel is not in the frame. The power lines distract a bit too. I think a panned shot with the background motion blurred might have been more striking. 4', '2010-02-16 12:47:41.000000', NULL, 1),
(5869170, 853070, 99263, '<td valign="top">This image has perspective but I find it rather uninspiring and a bit dull. 5</td>', 'This image has perspective but I find it rather uninspiring and a bit dull. 5', '2010-02-16 12:47:46.000000', NULL, 1),
(5869172, 852221, 99263, '<td valign="top">There''s perspective here and good B&amp;W conversion but there''s too much clutter at the top. 5</td>', 'There''s perspective here and good B&W conversion but there''s too much clutter at the top. 5', '2010-02-16 12:48:00.000000', NULL, 1);
