(5869237, 852893, 99263, '<td valign="top">Good perspective but not really a corker of an image. 4</td>', 'Good perspective but not really a corker of an image. 4', '2010-02-16 12:56:16.000000', NULL, 1),
(5869238, 852348, 99263, '<td valign="top">No perspective here and really horrible colors. Don''t get the title either. 4</td>', 'No perspective here and really horrible colors. Don''t get the title either. 4', '2010-02-16 12:56:22.000000', NULL, 1),
