(5870120, 852897, 94235, '<td valign="top">A little too blurry for me.</td>', 'A little too blurry for me.', '2010-02-16 23:37:25.000000', NULL, 1),
(5870121, 852962, 94235, '<td valign="top">Great angle and very effective take for the challenge.</td>', 'Great angle and very effective take for the challenge.', '2010-02-16 23:37:53.000000', NULL, 1),
