(5870128, 853172, 94235, '<td valign="top">Interesting take. Looks a little OOF to me.</td>', 'Interesting take. Looks a little OOF to me.', '2010-02-16 23:39:14.000000', NULL, 1),
(5870131, 852819, 94235, '<td valign="top">Great take for this challenge. Simple color but very pleasing effect on the viewer''s eye.</td>', 'Great take for this challenge. Simple color but very pleasing effect on the viewer''s eye.', '2010-02-16 23:40:28.000000', NULL, 1),
(5870132, 853217, 94235, '<td valign="top">No wonder, it looks so cold! Good take.</td>', 'No wonder, it looks so cold! Good take.', '2010-02-16 23:41:01.000000', NULL, 1),
(5870134, 852348, 94235, '<td valign="top">Looks a bit Andy Warhol-ish. Good effect and perspective.</td>', 'Looks a bit Andy Warhol-ish. Good effect and perspective.', '2010-02-16 23:41:50.000000', NULL, 1),
(5870135, 852963, 31456, '<td valign="top">Nice location, but a bit busy in some places and very empty in others. Very nice color, and you placed the main elements well. Sweet stars on the lights.<br/> <br/>ETA: Why is there a black band on the right? I don''t remember that being there before...<br/><br/><i>Message edited by author 2010-02-17 01:08:49.</i></td>', 'Nice location, but a bit busy in some places and very empty in others. Very nice color, and you placed the main elements well. Sweet stars on the lights. ETA: Why is there a black band on the right? I don''t remember that being there before...', '2010-02-16 23:42:02.000000', '2010-02-17 01:08:49.000000', 1),
(5870136, 852972, 94235, '<td valign="top">6.</td>', '6.', '2010-02-16 23:42:12.000000', NULL, 1),
(5870138, 852613, 31456, '<td valign="top">A bit centered and uninteresting to me. Good tones, though a bit more local contrast would''ve improved it IMO.</td>', 'A bit centered and uninteresting to me. Good tones, though a bit more local contrast would''ve improved it IMO.', '2010-02-16 23:42:47.000000', NULL, 1),
(5870140, 853092, 94235, '<td valign="top">Good use of DOF to convey the perspective message. Well done.</td>', 'Good use of DOF to convey the perspective message. Well done.', '2010-02-16 23:42:56.000000', NULL, 1),
(5870143, 851890, 54645, '<td valign="top">Beautiful scene. Good luck Josh!</td>', 'Beautiful scene. Good luck Josh!', '2010-02-16 23:43:28.000000', NULL, 1),
(5870144, 853214, 94235, '<td valign="top">What a hoot! Not for the owner though. Great angle.</td>', 'What a hoot! Not for the owner though. Great angle.', '2010-02-16 23:43:31.000000', NULL, 1),
(5870145, 852539, 31456, '<td valign="top">It''s nice, but it''s still just water droplets... not sure such a shallow DoF works here, I think a bit deeper (maybe the second one could be in half-focus?) would''ve been better.</td>', 'It''s nice, but it''s still just water droplets... not sure such a shallow DoF works here, I think a bit deeper (maybe the second one could be in half-focus?) would''ve been better.', '2010-02-16 23:43:53.000000', NULL, 1),
(5870146, 852510, 94235, '<td valign="top">Nice landscape.</td>', 'Nice landscape.', '2010-02-16 23:44:21.000000', NULL, 1),
(5870147, 852899, 31456, '<td valign="top">Nice colors, but the depth of field is a bit too shallow and the subject uninteresting.</td>', 'Nice colors, but the depth of field is a bit too shallow and the subject uninteresting.', '2010-02-16 23:44:44.000000', NULL, 1),
(5870148, 852399, 54645, '<td valign="top">I like tones of this version, but the perspective of the other. Good luck!</td>', 'I like tones of this version, but the perspective of the other. Good luck!', '2010-02-16 23:45:25.000000', NULL, 1),
(5870151, 852737, 31456, '<td valign="top">Well, it''s not an illegal effect... but I don''t think it improves your image much. I know this place from an image in a photo club, really cool place!</td>', 'Well, it''s not an illegal effect... but I don''t think it improves your image much. I know this place from an image in a photo club, really cool place!', '2010-02-16 23:45:47.000000', NULL, 1),
(5870152, 852852, 75618, '<td valign="top">Last minute bump to a 7 because of the excellent perspective</td>', 'Last minute bump to a 7 because of the excellent perspective', '2010-02-16 23:46:02.000000', NULL, 1),
(5870153, 852553, 31456, '<td valign="top">Kind of uninteresting, my eyes are looking for something to focus on and they keep getting pushed out of the image.</td>', 'Kind of uninteresting, my eyes are looking for something to focus on and they keep getting pushed out of the image.', '2010-02-16 23:46:21.000000', NULL, 1),
(5870157, 852868, 31456, '<td valign="top">Not that interesting of a perspective to me, and it''s a bit soft/grainy.</td>', 'Not that interesting of a perspective to me, and it''s a bit soft/grainy.', '2010-02-16 23:47:30.000000', NULL, 1),
(5870158, 852584, 94235, '<td valign="top">Would have liked this cropped a little more at the top to give the jetty a more stretched out perspective. Nice take and good shot all the same.</td>', 'Would have liked this cropped a little more at the top to give the jetty a more stretched out perspective. Nice take and good shot all the same.', '2010-02-16 23:47:31.000000', NULL, 1),
(5870159, 852644, 94235, '<td valign="top">Love to be there right now. Nice take.</td>', 'Love to be there right now. Nice take.', '2010-02-16 23:48:06.000000', NULL, 1),
(5870162, 853046, 94235, '<td valign="top">Great macro. I can just hear him saying ouch! ouch! ouch!</td>', 'Great macro. I can just hear him saying ouch! ouch! ouch!', '2010-02-16 23:48:53.000000', NULL, 1),
(5870163, 853048, 94235, '<td valign="top">Great color and effect. Nicely shot.</td>', 'Great color and effect. Nicely shot.', '2010-02-16 23:49:18.000000', NULL, 1),
(5870164, 853200, 94235, '<td valign="top">good capture.</td>', 'good capture.', '2010-02-16 23:49:32.000000', NULL, 1),
(5870165, 853069, 54645, '<td valign="top">Excellent. My backside feels cold just looking at that seat! Back to bump, favorite of the challenge. I want to see a little brother double dog dared to sit on that seat naked! 10</td>', 'Excellent. My backside feels cold just looking at that seat! Back to bump, favorite of the challenge. I want to see a little brother double dog dared to sit on that seat naked! 10', '2010-02-16 23:50:03.000000', NULL, 1),
(5870166, 852551, 94235, '<td valign="top">Look a little blurred to me.</td>', 'Look a little blurred to me.', '2010-02-16 23:50:13.000000', NULL, 1),
(5870167, 853069, 31456, '<td valign="top">This is really really cool. Literally and figuratively. If I were voting, I''d definitely give this a 10 (sorry I''m not). The clarity, the DoF, the composition, the tones, the concept, the execution... I don''t like the title.</td>', 'This is really really cool. Literally and figuratively. If I were voting, I''d definitely give this a 10 (sorry I''m not). The clarity, the DoF, the composition, the tones, the concept, the execution... I don''t like the title.', '2010-02-16 23:50:17.000000', NULL, 1),
(5870168, 853003, 94235, '<td valign="top">Effective take. Nicely done.</td>', 'Effective take. Nicely done.', '2010-02-16 23:50:35.000000', NULL, 1),
(5870169, 852224, 15511, '<td valign="top">Title is well conceived.<br/>This is like watching mounted video cameras; the viewer must turn their head to match the horizon for the brain to make sense of what it sees. That''s why we ride with our eyes parallel to the ground. I''m not sure your image would have as much impact if aligned the way we ride, especially among non-riders, but I just can''t look at this comfortably. It looks more about the bike and less about why we ride.</td>', 'Title is well conceived.This is like watching mounted video cameras; the viewer must turn their head to match the horizon for the brain to make sense of what it sees. That''s why we ride with our eyes parallel to the ground. I''m not sure your image would have as much impact if aligned the way we ride, especially among non-riders, but I just can''t look at this comfortably. It looks more about the bike and less about why we ride.', '2010-02-16 23:50:45.000000', NULL, 1),
(5870170, 852902, 94235, '<td valign="top">Well processed. Looks good in B&amp;W.</td>', 'Well processed. Looks good in B&W.', '2010-02-16 23:51:09.000000', NULL, 1),
(5870171, 852881, 54645, '<td valign="top">Absolutely fantastic. Symmetry is excellent. Has a <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=34938" rel="nofollow" target="_blank">Hotpasta</a> feel. 8</td>', 'Absolutely fantastic. Symmetry is excellent. Has a  Hotpasta feel. 8', '2010-02-16 23:51:28.000000', NULL, 1),
(5870172, 853219, 31456, '<td valign="top">This took me a while to understand, so kudos for that. Great take on the theme, and awesome execution. The amount of detail in the clouds is amazing... HDR done right? Or an amazing camera and great processing?</td>', 'This took me a while to understand, so kudos for that. Great take on the theme, and awesome execution. The amount of detail in the clouds is amazing... HDR done right? Or an amazing camera and great processing?', '2010-02-16 23:51:32.000000', NULL, 1),
(5870174, 852966, 94235, '<td valign="top">Good shot for the challenge but maybe a little less tilt.</td>', 'Good shot for the challenge but maybe a little less tilt.', '2010-02-16 23:51:48.000000', NULL, 1),
(5870175, 853232, 54645, '<td valign="top">Screams of the American Rat Race. Excellent. 9</td>', 'Screams of the American Rat Race. Excellent. 9', '2010-02-16 23:51:58.000000', NULL, 1),
(5870177, 852884, 94235, '<td valign="top">Lovely building and well captured.</td>', 'Lovely building and well captured.', '2010-02-16 23:52:13.000000', NULL, 1),
(5870178, 852958, 31456, '<td valign="top">Gets soft a bit early for me, but other than that it''s great. Nice contrast between the warm and cool tones.</td>', 'Gets soft a bit early for me, but other than that it''s great. Nice contrast between the warm and cool tones.', '2010-02-16 23:52:16.000000', NULL, 1),
(5870179, 853269, 94235, '<td valign="top">Well shot.</td>', 'Well shot.', '2010-02-16 23:52:34.000000', NULL, 1),
(5870180, 852918, 54645, '<td valign="top">It''s so clean!!!</td>', 'It''s so clean!!!', '2010-02-16 23:52:40.000000', NULL, 1),
(5870182, 852946, 94235, '<td valign="top">Good angle. Maybe cropped a little too tight on the bottom but a good shot all the same.</td>', 'Good angle. Maybe cropped a little too tight on the bottom but a good shot all the same.', '2010-02-16 23:53:18.000000', NULL, 1),
(5870183, 852364, 54645, '<td valign="top">I can hear it.</td>', 'I can hear it.', '2010-02-16 23:53:28.000000', NULL, 1),
