(5870593, 853069, 105130, '<td valign="top">Just like <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_F.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_F.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_F.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=103142" rel="nofollow" target="_blank">vawendy</a>, this was my highest vote in the challenge - great to see it here on the front page. Huge congratulations!</td>', 'Just like  vawendy, this was my highest vote in the challenge - great to see it here on the front page. Huge congratulations!', '2010-02-17 03:27:56.000000', NULL, 0),
